require __DIR__.'/../../src/bootstrap.php';$u=require_user();$q=db()->prepare('SELECT * FROM withdrawals WHERE user_id=? ORDER BY id DESC');$q->execute([$u['id']]);$rows=$q->fetchAll();
if(str_contains($_SERVER['HTTP_ACCEPT']??'','application/json'))json_response(['balance'=>$u['balance'],'withdrawals'=>$rows,'withdrawn_total'=>array_sum(array_column($rows,'amount'))]);
page('我的钱包',function()use($u,$rows){if(isset($_GET['receipt']))echo '<div class="notice" role="status">提现申请已完成，流水号 '.(int)$_GET['receipt'].'。最新余额及记录如下。</div>';echo '<div class="stats"><div><strong>¥'.h($u['balance']).'</strong><span>可用余额</span></div><div><strong>'.count($rows).'</strong><span>提现记录</span></div></div><section class="panel narrow"><h2>申请提现</h2><form action="/wallet/withdraw.php" method="post">'.csrf_field();form_input('amount','提现金额','10','number');echo '<button>确认提现</button></form></section><section class="panel"><h2>资金流水</h2><table><thead><tr><th>流水号</th><th>金额</th><th>时间</th></tr></thead><tbody>';foreach($rows as$row)echo '<tr><td>'.(int)$row['id'].'</td><td>¥'.h($row['amount']).'</td><td>'.h($row['created_at']).'</td></tr>';echo '</tbody></table></section>';},'我的钱包');
